// "Latest from the blog" cards on the main site.
//
// At build time the cards are rendered from the blog repo's posts.json when
// it is checked out next to this repo (../blog.ljwebmanagement.com), so the
// section is in the HTML for crawlers and no-JS visitors. In the browser,
// https://blog.ljwebmanagement.com/assets/js/latest-posts.js (generated by
// the blog on every publish) replaces them with the newest posts, so the
// main site never goes stale between its own builds.

const fs = require("fs");
const path = require("path");
const { ROOT, BLOG_URL, escapeHtml, truncate } = require("./util");
const { icon } = require("./chrome");

const POSTS_JSON = path.join(ROOT, "..", "blog.ljwebmanagement.com", "posts.json");
const WEBP_DIR = path.join(ROOT, "..", "blog.ljwebmanagement.com", "assets", "img", "posts", "webp");

let posts = null;
function load() {
  if (posts) return posts;
  posts = [];
  if (fs.existsSync(POSTS_JSON)) {
    posts = JSON.parse(fs.readFileSync(POSTS_JSON, "utf8")).sort((a, b) => new Date(b.date) - new Date(a.date));
  } else {
    console.warn("  blog posts.json not found next to this repo; latest-post cards will load client-side only");
  }
  return posts;
}

// Must match postCard() in the blog repo's scripts/templates.js so the
// client-side refresh swaps in identical markup.
function postCard(p) {
  const hasWebp = fs.existsSync(path.join(WEBP_DIR, p.slug + "-640.webp"));
  const img = hasWebp ? BLOG_URL + "/assets/img/posts/webp/" + p.slug + "-640.webp" : p.image ? BLOG_URL + "/" + p.image : "";
  return (
    '<a class="lj-card lj-post-card" href="' + BLOG_URL + "/posts/" + encodeURIComponent(p.slug) + '.html">' +
    (img ? '<span class="lj-post-card-media"><img src="' + img + '" width="640" height="360" alt="" loading="lazy" decoding="async"></span>' : "") +
    '<span class="lj-post-card-body"><span class="lj-post-card-meta">' +
    (p.category ? '<span class="lj-tag">' + escapeHtml(p.category) + "</span>" : "") +
    '<time datetime="' + p.date + '">' + escapeHtml(p.dateDisplay || p.date) + "</time></span>" +
    "<h3>" + escapeHtml(p.title) + "</h3>" +
    (p.excerpt ? "<p>" + escapeHtml(truncate(p.excerpt, 130)) + "</p>" : "") +
    '<span class="lj-link-arrow">Read article ' + icon("arrowRight") + "</span></span></a>"
  );
}

function latestPosts(count) {
  const list = load().slice(0, count);
  return '<div class="lj-grid lj-grid-3" data-lj-latest-posts data-count="' + count + '">' + list.map(postCard).join("") + "</div>";
}

module.exports = { latestPosts };
